    casadi_emval_struct* sparse(const DM& m) {













      return 0;


    }

    casadi_emval_struct* full_or_sparse(const DM& m, bool simplify=false) {
      if (m.is_dense()) {
        return full(m, simplify);
      } else {
        casadi_emval_struct* p = sparse(m);
        if (is_null(p)) return from_ptr(&m);
        return p;
      }
    }




























































































































